    28  int git_smart__store_refs(transport_smart *t, int flushes)
    29  {
    30          gitno_buffer *buf = &t->buffer;
    31          git_vector *refs = &t->refs;
    32          int error, flush = 0, recvd;
    33          const char *line_end = NULL;
    34          git_pkt *pkt = NULL;
    35          git_pkt_parse_data pkt_parse_data = { 0 };
    36          size_t i;
    37
    38          /* Clear existing refs in case git_remote_connect() is called again
    39           * after git_remote_disconnect().
    40           */
    41          git_vector_foreach(refs, i, pkt) {
    42                  git_pkt_free(pkt);
    43          }
    44          git_vector_clear(refs);
    45          pkt = NULL;
    46
    47          do {
    48                  if (buf->offset > 0)
    49                          error = git_pkt_parse_line(&pkt, &line_end, buf->data, buf->offset, &pkt_parse_data);
    50                  else
    51                          error = GIT_EBUFS;
    52
    53                  if (error < 0 && error != GIT_EBUFS)
    54                          return error;
    55
    56                  if (error == GIT_EBUFS) {
    57                          if ((recvd = gitno_recv(buf)) < 0)
    58                                  return recvd;
    59
    60                          if (recvd == 0) {
    61                                  git_error_set(GIT_ERROR_NET, "early EOF");
    62                                  return GIT_EEOF;
    63                          }
    64
    65                          continue;
    66                  }
    67
    68                  if (gitno_consume(buf, line_end) < 0)
    69                          return -1;
    70
    71                  if (pkt->type == GIT_PKT_ERR) {
    72                          git_error_set(GIT_ERROR_NET, "remote error: %s", ((git_pkt_err *)pkt)->error);
    73                          git__free(pkt);
    74                          return -1;
    75                  }
    76
    77                  if (pkt->type != GIT_PKT_FLUSH && git_vector_insert(refs, pkt) < 0)
    78                          return -1;
    79
    80                  if (pkt->type == GIT_PKT_FLUSH) {
    81                          flush++;
    82                          git_pkt_free(pkt);
    83                  }
    84          } while (flush < flushes);
    85
    86          return flush;
    87  }
