   750  static int add_push_report_sideband_pkt(git_push *push, git_pkt_data *data_pkt, git_str *data_pkt_buf)
   751  {
   752          git_pkt *pkt;
   753          git_pkt_parse_data pkt_parse_data = { 0 };
   754          const char *line, *line_end = NULL;
   755          size_t line_len;
   756          int error;
   757          int reading_from_buf = data_pkt_buf->size > 0;
   758
   759          if (reading_from_buf) {
   760                  /* We had an existing partial packet, so add the new
   761                   * packet to the buffer and parse the whole thing */
   762                  git_str_put(data_pkt_buf, data_pkt->data, data_pkt->len);
   763                  line = data_pkt_buf->ptr;
   764                  line_len = data_pkt_buf->size;
   765          }
   766          else {
   767                  line = data_pkt->data;
   768                  line_len = data_pkt->len;
   769          }
   770
   771          while (line_len > 0) {
   772                  error = git_pkt_parse_line(&pkt, &line_end, line, line_len, &pkt_parse_data);
   773
   774                  if (error == GIT_EBUFS) {
   775                          /* Buffer the data when the inner packet is split
   776                           * across multiple sideband packets */
   777                          if (!reading_from_buf)
   778                                  git_str_put(data_pkt_buf, line, line_len);
   779                          error = 0;
   780                          goto done;
   781                  }
   782                  else if (error < 0)
   783                          goto done;
   784
   785                  /* Advance in the buffer */
   786                  line_len -= (line_end - line);
   787                  line = line_end;
   788
   789                  error = add_push_report_pkt(push, pkt);
   790
   791                  git_pkt_free(pkt);
   792
   793                  if (error < 0 && error != GIT_ITEROVER)
   794                          goto done;
   795          }
   796
   797          error = 0;
   798
   799  done:
   800          if (reading_from_buf)
   801                  git_str_consume(data_pkt_buf, line_end);
   802          return error;
   803  }
